from pydantic import BaseModel, validator, Field
from typing import Optional

class Usuario(BaseModel):
    nombre: str = Field(..., min_length=2, max_length=50)
    email: str
    edad: int = Field(..., ge=0, le=150)
    rol: Optional[str] = "user"

    @validator("email")
    def email_valido(cls, v):
        if "@" not in v:
            raise ValueError("Email inválido")
        return v.lower()

u = Usuario(nombre="Ana", email="ANA@test.COM", edad=25)
print(u)

from fastapi import FastAPI, Query
from typing import Optional

app = FastAPI()

@app.get("/buscar")
def buscar(
    q: str = Query(..., min_length=1, description="Término de búsqueda"),
    pagina: int = Query(1, ge=1),
    limite: int = Query(10, ge=1, le=100),
    categoria: Optional[str] = None,
) -> dict:
    return {
        "query": q,
        "pagina": pagina,
        "limite": limite,
        "categoria": categoria,
    }

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI()

class Item(BaseModel):
    nombre: str
    precio: float
    disponible: bool = True

items_db: dict[int, Item] = {}

@app.post("/items", status_code=201)
def crear_item(item: Item) -> dict:
    item_id = len(items_db) + 1
    items_db[item_id] = item
    return {"id": item_id, **item.model_dump()}

from fastapi import APIRouter, Depends
from typing import Annotated

router = APIRouter(prefix="/usuarios", tags=["usuarios"])

def obtener_db():
    db = {"conexion": "activa"}
    try:
        yield db
    finally:
        pass  # cerrar conexión

DB = Annotated[dict, Depends(obtener_db)]

@router.get("/")
def listar(db: DB) -> list:
    return []

@router.get("/{user_id}")
def obtener(user_id: int, db: DB) -> dict:
    return {"id": user_id}

from fastapi import FastAPI, status
from fastapi.responses import JSONResponse

app = FastAPI()

@app.exception_handler(ValueError)
async def manejar_valor_error(request, exc):
    return JSONResponse(
        status_code=status.HTTP_400_BAD_REQUEST,
        content={"error": str(exc), "tipo": "ValueError"},
    )

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI()

@app.get("/items/{item_id}")
def obtener_item(item_id: int) -> dict:
    if item_id not in items_db:
        raise HTTPException(status_code=404, detail="Item no encontrado")
    return {"id": item_id, **items_db[item_id].model_dump()}

