router = APIRouter(prefix="/usuarios", tags=["usuarios"])

def obtener_db():
    db = {"conexion": "activa"}
    try:
        yield db
    finally:
        pass  # cerrar conexión

DB = Annotated[dict, Depends(obtener_db)]

@router.get("/")
def listar(db: DB) -> list:
    return []

@router.get("/{user_id}")
def obtener(user_id: int, db: DB) -> dict:
    return {"id": user_id}

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI()

class Item(BaseModel):
    nombre: str
    precio: float
    disponible: bool = True

items_db: dict[int, Item] = {}

@app.post("/items", status_code=201)
def crear_item(item: Item) -> dict:
    item_id = len(items_db) + 1
    items_db[item_id] = item
    return {"id": item_id, **item.model_dump()}

from fastapi import FastAPI, status
from fastapi.responses import JSONResponse

app = FastAPI()

@app.exception_handler(ValueError)
async def manejar_valor_error(request, exc):
    return JSONResponse(
        status_code=status.HTTP_400_BAD_REQUEST,
        content={"error": str(exc), "tipo": "ValueError"},
    )

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI()

@app.get("/items/{item_id}")
def obtener_item(item_id: int) -> dict:
    if item_id not in items_db:
        raise HTTPException(status_code=404, detail="Item no encontrado")
    return {"id": item_id, **items_db[item_id].model_dump()}

from fastapi import FastAPI, Query
from typing import Optional

app = FastAPI()

@app.get("/buscar")
def buscar(
    q: str = Query(..., min_length=1, description="Término de búsqueda"),
